export default JSON.parse("{\"workId\":\"wenzi\",\"chapter\":{\"id\":\"wenzi_ch-2\",\"workId\":\"wenzi\",\"order\":2,\"title\":\"精誠\",\"difficulty\":2,\"estimatedMinutes\":34,\"passageIds\":[\"wenzi_ch-2_p-1\",\"wenzi_ch-2_p-2\",\"wenzi_ch-2_p-3\",\"wenzi_ch-2_p-4\",\"wenzi_ch-2_p-5\",\"wenzi_ch-2_p-6\",\"wenzi_ch-2_p-7\",\"wenzi_ch-2_p-8\",\"wenzi_ch-2_p-9\",\"wenzi_ch-2_p-10\",\"wenzi_ch-2_p-11\",\"wenzi_ch-2_p-12\",\"wenzi_ch-2_p-13\",\"wenzi_ch-2_p-14\",\"wenzi_ch-2_p-15\",\"wenzi_ch-2_p-16\",\"wenzi_ch-2_p-17\",\"wenzi_ch-2_p-18\",\"wenzi_ch-2_p-19\",\"wenzi_ch-2_p-20\",\"wenzi_ch-2_p-21\"],\"tags\":[]},\"passages\":[{\"id\":\"wenzi_ch-2_p-1\",\"chapterId\":\"wenzi_ch-2\",\"order\":1,\"canonicalText\":\"老子曰：天致其高，地致其厚，日月照，列星朗，陰陽和，非有為焉，正其道而物自然。陰陽四時非生萬物也，雨露時降非養草木也，神明接，陰陽和，萬物生矣。夫道者，藏精於內，棲神於心，靜漠恬惔，悅穆胸中，廓然無形，寂然無聲。官府若無事，朝廷若無人，無隱士，無逸民，無勞役，無怨刑，天下莫不仰上之象，主之旨，絕國殊俗莫不重譯而至，非家至而人見之也，推其誠心，施之天下而已。故賞善罰暴者，正令也；其所以能行者，精誠也。令雖明不能獨行，必待精誠，故摠道以被民弗從者，精誠弗包也。\",\"sentenceIds\":[\"wenzi_ch-2_p-1_s-1\",\"wenzi_ch-2_p-1_s-2\",\"wenzi_ch-2_p-1_s-3\",\"wenzi_ch-2_p-1_s-4\",\"wenzi_ch-2_p-1_s-5\",\"wenzi_ch-2_p-1_s-6\",\"wenzi_ch-2_p-1_s-7\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：天達到它的高度，地達到它的厚度，日月照耀、羣星明朗、陰陽和諧，並非刻意造作，只是各自端正其運行法則，萬物便自然化生。陰陽四時不是有意去生萬物，雨露按時降下也不是有意養育草木；神明之氣交接、陰陽和合，萬物便得以生長。所謂道，是把精氣藏在內部，使精神安住於心；保持寂靜恬淡、內心和悅，空曠而無形，寂然而無聲。依此治理，官府好像沒有繁事，朝廷好像沒有人刻意操弄；沒有被迫隱居的士人，也沒有逃離政令的人民，沒有繁重勞役，也沒有因刑罰不公而生的怨恨。天下都景仰君上的儀表、遵從君主的旨意；遠方異國即使要經過多重翻譯也前來，不是君主逐家走訪、逐人接見，而只是把真誠之心推廣施行於天下。因此獎賞善者、懲罰暴者，是端正的命令；命令之所以能實行，靠的卻是內在精誠。法令即使明白，也不能自行生效，必須等待精誠支撐。所以統合大道施及人民而人民仍不服從，原因是精誠沒有把他們包容在內。\",\"analysis\":\"【主旨】本段區分「政令正確」與「政令真正生效」：賞善罰暴只是制度表層，能使遠近信服的是統治者內在精誠及低擾動的治理實踐。\\\\n【章法與訓詁】開頭以天地日月不刻意而萬物自化作譬喻，中段描畫「官府若無事」的政治效果，末段以「令雖明不能獨行」點題。「重譯而至」指遠國語言多重轉譯後來朝；「摠道」即統合、總持大道。\\\\n【倫理界限】精誠不能取代制度、程序與權利保障；文中的無事政治應理解為減少擾民與命令能取得信任，不是取消行政責任。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-2\",\"chapterId\":\"wenzi_ch-2\",\"order\":2,\"canonicalText\":\"老子曰：天設日月，列星辰，張四時，調陰陽。日以暴之，夜以息之，風以乾之，雨露以濡之。其生物也，莫見其所養而萬物長；其殺物也，莫見其所喪而萬物亡。此謂神明。是故聖人象之，其起福也，不見其所以而福起；其除禍也，不見其所由而禍除。稽之不得，察之不虛，日計不足，歲計有餘，寂然無聲，一言而大動天下，是以天心動化者也。故精誠內形，氣動於天，景星見，黃龍下，鳳皇至，醴泉出，嘉穀生，河不滿溢，海不波湧；逆天暴物，即日月薄蝕，五星失行，四時相乘，晝明宵光，山崩川涸，冬雷夏霜。天之與人，有以相通，故國之沮亡也，天文變，世或亂，虹蜺見，萬物有以相連，精氣有以相薄，故神明之事，不可以智巧為也，不可以強力致也。故大人與天地合德，與日月合明，與鬼神合靈，與四時合信，懷天心，抱地氣，執沖含和，不下堂而行四海，變易習俗，民化遷善，若生諸己，能以神化者也。\",\"sentenceIds\":[\"wenzi_ch-2_p-2_s-1\",\"wenzi_ch-2_p-2_s-2\",\"wenzi_ch-2_p-2_s-3\",\"wenzi_ch-2_p-2_s-4\",\"wenzi_ch-2_p-2_s-5\",\"wenzi_ch-2_p-2_s-6\",\"wenzi_ch-2_p-2_s-7\",\"wenzi_ch-2_p-2_s-8\",\"wenzi_ch-2_p-2_s-9\",\"wenzi_ch-2_p-2_s-10\",\"wenzi_ch-2_p-2_s-11\",\"wenzi_ch-2_p-2_s-12\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：天佈置日月星辰，展開四時，調節陰陽；白日以陽光曝曬萬物，夜間讓它們休息，風使它們乾燥，雨露使它們濕潤。天生養萬物時，人看不見它如何養育，萬物卻持續生長；它使萬物凋亡時，人看不見它奪去什麼，萬物卻自然消逝，這叫神明。因此聖人取法於此：興起福祉時，人看不見具體原因，福祉卻已形成；消除禍患時，人看不見禍患從何消除，它卻已消退。想逐項稽考難以找到，仔細觀察又並非虛假；按日計算好像不足，按年計算卻綽有餘裕。它寂然無聲，有時一句話便能大大感動天下，這是以合乎天心的方式推動教化。所以古人相信，精誠在內形成，氣便上感於天，於是景星出現、黃龍下降、鳳凰到來、甘泉湧出、嘉穀生長，河不氾濫、海不起巨浪；若違逆天理、殘害萬物，便會有日月蝕、五星失序、四時錯亂、晝暗夜明、山崩川涸、冬雷夏霜等異象。天與人似有相通之處；國家將衰亡時，天象變異，世道混亂時虹霓出現。萬物彼此相連，精氣互相感迫，因此神明之事不能以智巧偽造，也不能靠強力取得。所以大人使德性與天地相合，明察與日月相合，靈應與鬼神相合，信用與四時相合；胸懷天心、抱持地氣，守虛和、含中和，不出堂室而影響四海，改變習俗，使人民受化而遷善，彷彿這些善行都由自己內在生出，這就是以精神感化。\",\"analysis\":\"【主旨與章法】本段先由日月風雨的無聲作用說教化須累積而成，再以祥瑞災異建立天人感應圖式，最後描寫大人以內在精誠移風易俗。中心仍是「日計不足，歲計有餘」：真正影響常在長期中顯現。\\\\n【名物】景星、黃龍、鳳凰、醴泉、嘉穀是傳統政治祥瑞；日月薄蝕、五星失行、冬雷夏霜則被視作失政災異。「四時相乘」指季節秩序彼此侵凌錯位。\\\\n【史料與科學界限】祥瑞災異屬古代天人感應政治語言，不能當作君主德行會直接控制天文、氣象或地質事件的現代科學證據；其思想史作用在於用宇宙秩序約束政治權力。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-3\",\"chapterId\":\"wenzi_ch-2\",\"order\":3,\"canonicalText\":\"老子曰：夫人道者，全性保真，不虧其身，遭急迫難，精通乎天，若乃未始出其宗者，何為而不成，死生同域，不可脅凌，又況官天地，懷萬物，返造化，含至和，而已未嘗死者也。精誠形乎內，而外喻於人心，此不傳之道也。聖人在上，懷道而不言，澤及萬民，故不言之教，芒乎大哉！君臣乖心，倍譎見於天，神氣相應，微矣，此謂不言之辯，不道之道也。夫召遠者使無為焉，親近者言無事焉，唯夜行者能有之，卻走馬以糞，車軌不接於遠方之外，是謂坐馳陸沉。天道無私就也，無私去也，能者有餘，詘者不足，順之者利，逆之者兇。是故以智為治者難以持國，唯同乎大和而持自然應者，為能有之。\",\"sentenceIds\":[\"wenzi_ch-2_p-3_s-1\",\"wenzi_ch-2_p-3_s-2\",\"wenzi_ch-2_p-3_s-3\",\"wenzi_ch-2_p-3_s-4\",\"wenzi_ch-2_p-3_s-5\",\"wenzi_ch-2_p-3_s-6\",\"wenzi_ch-2_p-3_s-7\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：人的正道，在於保全本性、保存真實，不損害自身。即使遭遇急迫危難，精神仍與天道相通。若從未離開自己的根本，做什麼不能成就呢？他把生死視為同一變化領域，不會被威脅欺凌。何況那些以天地為官府、胸懷萬物、返回造化根源、含養最高和氣，而精神未嘗隨形體死亡的人呢！精誠形成於內，便能在外感通人心，這是不能只靠言語傳授的道。聖人在上位，心懷大道而不多言，恩澤卻遍及萬民；所以不言之教極其廣大。君臣若離心，背逆欺詐的徵兆會顯現於天；精神氣象彼此感應，極其微妙。這叫不用言語的辨明、不靠宣說的道。要招致遠方的人，不在多所作為；要親近近處的人，不在多事多言。只有能在幽暗中體道的人才能做到。那時戰馬退回用於耕作積肥，車轍不延伸到遙遠國境之外；人雖安坐，精神卻能遠行，形跡雖沉潛，德化卻能遠達。天道不偏私地親近誰，也不偏私地離開誰；有能力順應的人便有餘，不能伸展的人便不足，順從它便得利，違逆它便遭兇。因此，只靠機智治理的人難以保有國家；唯有契合大和、持守自然感應的人，才真正能保有天下。\",\"analysis\":\"【主旨】本段說明「精誠」由保全真性開始，能超越言語與距離而感通人心，成為治國的深層力量。\\\\n【關鍵詞義】「未始出其宗」是未離生命根本；「不言之教」是以德行而非口號感化；「卻走馬以糞」指使戰馬退回農用，象徵止息征伐；「坐馳陸沉」在此表現形跡不動而精神德化遠行。\\\\n【章法與思想】篇章由個人全性保真推到君臣感應、遠人來服，再以天道無私作結。它不否認政令，而強調單靠智術和外在動作不能建立持久秩序。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-4\",\"chapterId\":\"wenzi_ch-2\",\"order\":4,\"canonicalText\":\"老子曰：夫道之與德，若圍之與革，遠之即近，近之即鉕，稽之不得，察之不虛。是故聖人若鏡，不將不迎，應而不藏，不物而不傷。其得之也，乃失之也，其失之也，乃得之也，故通於大和者，闇若醇醉而甘臥以遊其中，若未始出其宗，是謂大通，此假不用能成其用也。\",\"sentenceIds\":[\"wenzi_ch-2_p-4_s-1\",\"wenzi_ch-2_p-4_s-2\",\"wenzi_ch-2_p-4_s-3\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：道與德的關係，好像車輪外圈與包裹其上的皮革，彼此相依；看似疏遠其實相近，看似接近卻又難以固定把握。考求它不能取得實體，細察它又並非虛無。因此聖人像鏡子一樣，不預先送走，也不刻意迎接；事物來了便如實回應，映照過後不加收藏，不因外物而傷害自己。刻意佔有它，反而會失去；不自以為佔有，反而真正得到。所以通達大和的人，昏昏然像醇醉後安睡，悠遊其中，彷彿從未離開根本，這叫大通。正因不假借智巧、不刻意使用，才能真正成就它的作用。\",\"analysis\":\"【題解與背景】\\\\n本段選自《文子》〈精誠〉第 13 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰夫道之與德若圍之與革遠之即近近之即……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「老」、「子」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wenzi_ch-2_p-4）。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-5\",\"chapterId\":\"wenzi_ch-2\",\"order\":5,\"canonicalText\":\"老子曰：昔黃帝之治天下，理日月之行，治陰陽之氣，節四時之度，正律曆之數，別男女，明上下，使強不掩弱，眾不暴寡，民保命而不夭，歲時熟而不兇，百官正而無私，上下調而無尤，法令明而不闇，輔佐公而不阿，田者讓畔，道不拾遺，市不預賈，故於此時，日月星辰不失其行，風雨時節，五穀豐昌，鳳皇翔於庭，麒麟遊於郊。虙犧氏之王天下，枕方寢繩，殺秋約冬，負方州，抱員天，陰陽所擁沈不通者竅理之，逆氣戾物傷民厚積者絕止之，其民童蒙不知西東，視瞑瞑，行蹎蹎，侗然自得，莫知其所由，浮游汎然，不知所本，罔養不知所如往，當此之時，禽獸蟲蛇無不懷其爪牙，藏其螫毒，功揆天地。至黃帝要繆乎太祖之下，然而不章其功，不揚其名，隱真人之道，以從天地之固然，何即道德上通，而智故消滅也。\",\"sentenceIds\":[\"wenzi_ch-2_p-5_s-1\",\"wenzi_ch-2_p-5_s-2\",\"wenzi_ch-2_p-5_s-3\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：從前黃帝治理天下，調理日月運行，調和陰陽之氣，節制四季尺度，校正音律曆法；辨明男女之別與上下秩序，使強者不壓迫弱者，多數不欺凌少數。人民保全天年而不夭折，年歲豐熟而沒有饑荒；百官端正無私，上下和諧無怨；法令明白不昏暗，輔臣奉公不阿諛。耕田者互讓田界，道路上遺物無人拾取，市場不預先囤積牟利。因此日月星辰不失常軌，風雨合時，五穀豐盛，鳳凰飛翔於宮庭，麒麟遊於郊野。伏羲氏統治天下時，以方正為枕，以準繩為席；秋季節制殺伐，冬季約束收藏，背負方形大地，懷抱圓形天空。凡陰陽壅塞不通之處，便加以疏理；凡逆氣乖戾、傷害人民而積聚深厚之處，便加以制止。那時人民如童蒙，不辨東西；目光樸鈍，行步安緩，渾然自得，不知道所以如此。他們自在浮游，不追問根本，涵養其中也不知道將往何方。禽獸蟲蛇都收起爪牙，藏起螫毒；伏羲的功效與天地相合。到黃帝在始祖神廟前恭敬祭享，仍不彰顯功業、不宣揚名聲；隱藏真人之道，順從天地本然。為什麼呢？因為道德向上與天相通，機巧智詐便自然消失。\",\"analysis\":\"【主旨】本段並舉黃帝的明制度與伏羲的無跡教化，理想共同點是抑強暴、安生命而不自彰功名。\\\\n【關鍵詞義】「田者讓畔」是耕者互讓田界；「市不預賈」可理解為不預囤居奇；「員天」即圓天；「揆天地」是功效符合天地尺度。\\\\n【版本提示】「枕方寢繩」「殺秋約冬」「要繆乎太祖之下」均有斷讀與異文疑問；白話依守方繩、順秋冬、在祖廟恭敬的傳統註解方向暫譯，不標作已定本。\\\\n【史境】鳳凰、麒麟等是古代祥瑞敘事；其作用是象徵政治和諧，而非可驗證的歷史紀錄。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-6\",\"chapterId\":\"wenzi_ch-2\",\"order\":6,\"canonicalText\":\"老子曰：天不定，日月無所載，地不定，草木無所立，身不寧，是非無所形，是故有真人而後有真智，其所持者不明，何知吾所謂知之非不知與？積惠重貨，使萬民欣欣，人樂其生者，仁也；舉大功，顯令名，體君臣，正上下，明親疏，存危國，繼絕世，立無後者，義也；閉九竅，藏志意，棄聰明，反無識，芒然仿佯乎塵垢之外，逍遙乎無事之業，含陰吐陽而與萬物同和者，德也。是故道散而為德，德溢而為仁義，仁義立而道德廢矣。\",\"sentenceIds\":[\"wenzi_ch-2_p-6_s-1\",\"wenzi_ch-2_p-6_s-2\",\"wenzi_ch-2_p-6_s-3\",\"wenzi_ch-2_p-6_s-4\",\"wenzi_ch-2_p-6_s-5\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：天若不安定，日月便無所承載；地若不安定，草木便無處生立；自身若不能寧靜，是非也就無從顯明。因此先有真人，然後纔有真知。如果連他所持守的根本都不明白，又怎能知道我所說的知，不是世俗所以為的不知呢？廣施恩惠、厚贈財貨，使萬民欣悅、樂於生活，這叫作仁；建立大功、彰顯美名，規範君臣、端正上下、辨明親疏，保存危亡之國、延續斷絕的世系、替無後者立嗣，這叫作義；收斂耳目口鼻等感官，深藏心志，捨棄自作聰明，返回無知無識的境地，茫然徜徉於塵垢之外，逍遙於無事的境界，涵養陰氣、吐納陽氣，與萬物共同和諧，這叫作德。所以道分散而表現為德，德向外流溢而表現為仁義；等到仁義被特意樹立，道德的根本反而衰廢了。\",\"analysis\":\"【主旨】本段區分道、德、仁、義的層次：仁義是道德向外落實後的制度與功業，若只標榜仁義之名而失去內在寧靜，反會遮蔽根本。\\\\n【關鍵詞義】「真人」指持守真實本性、不受外物擾亂的人；「閉九竅」不是生理封閉，而是收斂感官追逐；「反無識」是放下分別計較，不能理解成拒絕知識。\\\\n【章法與思想】先以天地安定比喻身心安定是判斷的前提，再依次界定仁、義、德，最後提出「道散為德，德溢為仁義」。結語批評的是捨本逐末的仁義標榜，不是否定救民、正名與存亡繼絕的實際價值。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-7\",\"chapterId\":\"wenzi_ch-2\",\"order\":7,\"canonicalText\":\"老子曰：神越者言華，德蕩者行偽，至精芒乎中，而言行觀乎外，此不免以身役物也。精有愁盡而行無窮極，所守不定而外淫於世俗之風，是故聖人內脩道術而不外飾仁義，知九竅四支之宜，而遊乎精神之和，此聖人之遊也。\",\"sentenceIds\":[\"wenzi_ch-2_p-7_s-1\",\"wenzi_ch-2_p-7_s-2\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：精神向外浮越的人，言語華麗；德性蕩失的人，行為虛偽。最精純的精神在內昏亂，言語行動卻只供外界觀看，這樣終究免不了役使自身去迎合外物。人的精神有憂愁耗盡之時，外在追逐卻沒有窮極；內心所守不定，便向外沉溺於世俗風氣。因此聖人在內修養道術，而不在外表粉飾仁義；明白眼耳口鼻等九竅與四肢的適當運用，遨遊於精神和諧的境界，這才是聖人的遊心。\",\"analysis\":\"【題解與背景】\\\\n本段選自《文子》〈精誠〉第 16 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰神越者言華德蕩者行偽至精芒乎中而言行觀……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「神」、「越」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-8\",\"chapterId\":\"wenzi_ch-2\",\"order\":8,\"canonicalText\":\"老子曰：若夫聖人之遊也，即動乎至虛，遊心乎太無，馳於方外，行於無門，聽於無聲，視於無形，不拘於世，不繫於俗。故聖人所以動天下者，真人不過，賢人所以矯世者，聖人不觀。夫人拘於世俗，必形繫而神泄，故不免於別，使我可拘係者，必其命有在外者。\",\"sentenceIds\":[\"wenzi_ch-2_p-8_s-1\",\"wenzi_ch-2_p-8_s-2\",\"wenzi_ch-2_p-8_s-3\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：至於聖人的遨遊，是活動於極度虛靜之中，使心神遊於廣大的無形境界，馳騁於常規之外，行走於沒有固定門徑之處；聽無聲之聲，見無形之形，不受世情拘束，不被習俗繫縛。因此聖人用來感動天下的作為，真人並不刻意追求；賢人用來矯正世俗的措施，聖人也不執著觀看。人若拘泥世俗，形體必被牽繫，精神必然洩散，因而不能免於分別對待。能使我被拘束牽繫的，必是我把生命的依歸寄託在外物。\",\"analysis\":\"【主旨】本段把自由的關鍵放在生命依歸：若將價值安置於名位、評價等外物，形神便受制；聖人則由虛靜中回應世界，不把矯世事功當作自我根基。\\\\n【關鍵詞義】「方外」是既定常規之外；「無門」不是沒有方法，而是不固守單一路徑；「真人不過」可理解為真人不以感動天下為更高追求；「命有在外」是把生命價值寄託於外。\\\\n【版本提示】「不免於別」可能有異文或特殊義，白話依受俗拘繫而陷入分別的脈絡暫譯。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-9\",\"chapterId\":\"wenzi_ch-2\",\"order\":9,\"canonicalText\":\"老子曰：人主之思，神不馳於胸中，智不出於四域，懷其仁誠之心，甘雨以時，五穀蕃殖，春生夏長，秋收冬藏，月省時考，終歲獻貢，養民以公，威厲以誠，法省不煩，教化如神，法寬刑緩，囹圄空虛，天下一俗，莫懷姦心，此聖人之思也。夫上好取而無量，即下貪功而無讓，民貧苦而分爭生，事力勞而無功，智詐萌生，盜賊滋彰，上下相怨，號令不行，夫水濁者魚噞，政苛者民亂，上多欲即下多詐，上煩擾即下不定，上多求即下交爭，不治其本而救之於末，無以異於鑿渠而止水，抱薪而救火。聖人事省而治求，寡而贍，不施而仁，不言而信，不求而得，不為而成，懷自然，保至真，抱道推誠，天下從之如響之應聲，影之像形，所脩者本也。\",\"sentenceIds\":[\"wenzi_ch-2_p-9_s-1\",\"wenzi_ch-2_p-9_s-2\",\"wenzi_ch-2_p-9_s-3\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：君主的思慮，應使精神不在胸中躁動奔馳，才智不向四境外逐；懷抱仁愛真誠之心，甘雨便按時而降，五穀繁殖，春生夏長、秋收冬藏。每月省察，按季考核，年終接受貢賦；以公正養護人民，以誠信建立威嚴。法令簡省而不繁瑣，教化自然得像神妙一般；法律寬平、刑罰舒緩，監獄空虛，天下風俗一致，無人心懷奸詐，這是聖人的思慮。若上位者貪取沒有節制，下級便爭功而不謙讓；人民貧困，爭端隨之產生，勞力耗盡卻沒有成果，機詐萌生，盜賊日多，上下彼此怨恨，號令不能施行。水混濁，魚便張口喘息；政治苛刻，人民便混亂。上位者欲望多，下級欺詐便多；上位者煩擾，下級便不安定；上位者索求多，下級便互相爭奪。不治理根本，只在末端補救，和開鑿水渠卻想止水、抱著柴草去救火沒有不同。聖人事務簡省，治理卻有成效；取用少而供給充足，不刻意施惠而有仁，不多言而可信，不強求而有所得，不妄作而能成功。懷抱自然，保存至真，守道而推行誠意，天下便像回聲應聲、影子隨形一樣跟從，因為他所修治的是根本。\",\"analysis\":\"【題解與背景】\\\\n本段選自《文子》〈精誠〉第 18 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰人主之思神不馳於胸中智不出於四域懷其仁……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「人」、「主」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-10\",\"chapterId\":\"wenzi_ch-2\",\"order\":10,\"canonicalText\":\"老子曰：精神越於外，智慮蕩於內者，不能治形，神之所用者遠，則所遺者近。故「不出於戶以知天下，不窺於牖以知天道，其出彌遠，其知彌少。」此言精誠發於內，神氣動於天也。\",\"sentenceIds\":[\"wenzi_ch-2_p-10_s-1\",\"wenzi_ch-2_p-10_s-2\",\"wenzi_ch-2_p-10_s-3\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：精神向外奔越、思慮在內激蕩的人，不能治理自己的形體；精神所追逐的地方愈遠，遺忘的眼前根本便愈多。所以說：不走出門戶便能知曉天下，不窺看窗外便能明白天道；走得愈遠，知道的反而愈少。這是說，精純誠意從內心發出，精神之氣便能感通於天。\",\"analysis\":\"【題解與背景】\\\\n本段選自《文子》〈精誠〉第 19 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰精神越於外智慮蕩於內者不能治形神之所用……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「精」、「神」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-11\",\"chapterId\":\"wenzi_ch-2\",\"order\":11,\"canonicalText\":\"老子曰：冬日之陽，夏日之陰，萬物歸之而莫之使，極自然至精之感，弗召自來，不去而往，窈窈冥冥，不知所為者而功自成，待目而照見，待言而使命，其於治難矣。皋陶喑而為大理，天下無虐刑，有貴乎言者也，師曠瞽而為太宰，晉國無亂政，有貴乎見者也。不言之令，不視之見，聖人所以為師也，民之化上，不從其言從其所行，故人君好勇，弗使鬥爭而國家多難，其漸必有劫殺之亂矣。人君好色，弗使風議而國家昏亂，其積至於淫泆之難，故聖人精誠別於內，好憎明於外，出言以副情，發號以明指。是故刑罰不足以移風，殺戮不足以禁姦，唯神化為貴，精至為神，精之所動，若春氣之生，秋氣之殺。故君子者，其猶射者也，於此毫末，於彼尋丈矣！故理人者，慎所以感之。\",\"sentenceIds\":[\"wenzi_ch-2_p-11_s-1\",\"wenzi_ch-2_p-11_s-2\",\"wenzi_ch-2_p-11_s-3\",\"wenzi_ch-2_p-11_s-4\",\"wenzi_ch-2_p-11_s-5\",\"wenzi_ch-2_p-11_s-6\",\"wenzi_ch-2_p-11_s-7\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：冬日的陽氣、夏日的陰氣，萬物自然歸向它們，卻沒有人加以驅使；這是極其自然、最為精微的感應。不召喚而自來，不驅逐而自往，幽深昏冥，看不出刻意作為，功效卻自然完成。若事事都要等眼睛看見才明白，等言語命令才行動，治理便很困難了。皋陶雖不善言辭，擔任最高司法官，天下卻沒有酷刑，可見有比言語更可貴的東西；師曠雖然失明，擔任晉國太宰，晉國卻沒有亂政，可見有比目視更可貴的東西。不用言語而能施令，不靠眼見而能明察，正是聖人足以為人師法之處。人民受在上者感化，不只聽從他的言辭，更仿效他的實際行為。因此君主若好勇，即使沒有命令人爭鬥，國家仍會多難，逐漸必生劫奪殺戮之亂；君主若好色，即使沒有公開倡議，國家仍會昏亂，累積下去必成淫逸之禍。所以聖人使精誠在內心分明，使喜好厭惡在外表清楚；言語符合真情，號令表明旨意。因此刑罰不足以改變風俗，殺戮不足以禁止奸邪，只有不言而化最為可貴。精誠達到極致便近於神妙；它所引發的變化，就像春氣使萬物生長、秋氣使萬物凋落。君子的影響好比射箭：在發端處只差毫末，到達遠處便可能相差數丈。因此治理人民的人，必須慎重自己用來感動人民的根源。\",\"analysis\":\"【主旨】政治教化主要來自統治者真實而持續的行為示範，不是口頭命令或刑罰；上位者細微的偏好，會在社會中被放大。\\\\n【關鍵詞義】「大理」是掌刑獄的官職；「有貴乎言／見」意謂另有比言語、目視更重要的內在精誠；「毫末／尋丈」用射箭比喻起點微差、末端巨差。\\\\n【章法與思想】先以冬陽夏陰說自然感應，再舉皋陶、師曠說不恃言視，繼而以好勇、好色展示負面感化，最後用春生秋殺與射箭收束。這使「神化」具有可理解的政治意義：身教形成風氣，並非訴諸神怪。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-12\",\"chapterId\":\"wenzi_ch-2\",\"order\":12,\"canonicalText\":\"老子曰：懸法設賞而不能移風易俗者，誠心不抱，故聽其音則知其風，觀其樂即知其俗，見其俗即知其化。夫抱真效誠者，感動天地，神踰方外，令行禁止，誠通其道而達其意，雖無一言，天下萬民、禽獸、鬼神與之變化。故太上神化，其次使不得為非，其下賞賢而罰暴。\",\"sentenceIds\":[\"wenzi_ch-2_p-12_s-1\",\"wenzi_ch-2_p-12_s-2\",\"wenzi_ch-2_p-12_s-3\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：公布法令、設置獎賞，卻不能移風易俗，是因為內心沒有抱持真誠。所以聽一地的聲音便可知道它的風氣，觀察它的音樂便可知道它的習俗，看見它的習俗便可知道教化情形。抱守真性、實踐誠意的人，能感動天地，精神超越四方；命令能施行，禁令能制止，是因真誠貫通其道、傳達其心意。即使一句話也不說，天下萬民乃至禽獸、鬼神也隨他變化。因此最高層次是無形的精神感化，其次是使人沒有條件作惡，最低層次才是獎賞賢者、懲罰暴徒。\",\"analysis\":\"【題解與背景】\\\\n本段選自《文子》〈精誠〉第 21 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰懸法設賞而不能移風易俗者誠心不抱故聽其……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「懸」、「法」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-13\",\"chapterId\":\"wenzi_ch-2\",\"order\":13,\"canonicalText\":\"老子曰：大道無為，無為即無有，無有者不居也，不居者即處無形，無形者不動，不動者無言也，無言者即靜而無聲無形，無聲無形者，視之不見，聽之不聞，是謂微妙，是謂至神，「綿綿若存」，「是謂天地根。」道無聲，故聖人強為之形，以一句為名天地之道。大以小為本，多以少為始，天子以天地為品，以萬物為資，功德至大，勢名至貴，二德之美與天地配，故不可不軌大道以為天下母。\",\"sentenceIds\":[\"wenzi_ch-2_p-13_s-1\",\"wenzi_ch-2_p-13_s-2\",\"wenzi_ch-2_p-13_s-3\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：大道無所造作；無為便不佔有事物，不佔有便不居功，既不居功便處於無形。無形便不妄動，不妄動便無須言說；無言便寂靜，沒有聲音也沒有形象。無聲無形，觀看它看不見，聆聽它聽不到，這叫微妙，這叫最神妙。綿綿不絕，若有若存，這叫天地的根源。道本來無聲，所以聖人勉強替它描摹形狀，用一句名稱來指稱天地之道。大以小為根本，多從少開始。天子以天地萬類為品物，以萬物作資用；功德極大，權勢名位極尊貴，所具二德之美可與天地相配，所以不可不遵循大道，把它作為天下萬物之母。\",\"analysis\":\"【題解與背景】\\\\n本段選自《文子》〈精誠〉第 22 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰大道無為無為即無有無有者不居也不居者即……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「大」、「道」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-14\",\"chapterId\":\"wenzi_ch-2\",\"order\":14,\"canonicalText\":\"老子曰：振窮補急則名生利起，除害即功成，世無災害，雖聖無所施其德，上下和睦，雖賢無所立其功。故至人之治，含德抱道，推誠施無窮之智，寢說而不言天下莫知貴其不言者，故「道可道，非常道也，名可名，非常名也。」著於竹帛，鏤於金石，可傳於人者，皆其麤也。三皇五帝三王，殊事而同心，異路而同歸，末世之學者，不知道之所體一德之所摠要取成事之跡跪坐而言之，雖博學多聞，不免於亂。\",\"sentenceIds\":[\"wenzi_ch-2_p-14_s-1\",\"wenzi_ch-2_p-14_s-2\",\"wenzi_ch-2_p-14_s-3\",\"wenzi_ch-2_p-14_s-4\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：救濟困窮、補助急難，名聲與利益便會興起；消除禍害，功業便會成立。假使世上本來沒有災害，即使聖人也無處施展其德；上下本來和睦，即使賢者也無處建立其功。所以至人的治理，是內含德、懷抱道，推行真誠並運用無窮智慧，止息辯說而不多言；天下人卻不知道應以他的不言為可貴。因此說：可以說出的道，不是恆常之道；可以命名的名，不是恆常之名。凡寫在竹帛、刻在金石、可以用文字傳授給人的，都只是大道粗淺的外跡。三皇、五帝、三王所行之事不同，內心宗旨卻相同；所走道路不同，歸宿卻一致。末世學者不知道道所體現的是一、不知道德所統攝的要領，只拾取前人成事的痕跡，端坐談論；即使博學多聞，也不能免於混亂。\",\"analysis\":\"【主旨】本段區分道的共同根本與歷代制度留下的外在事跡，批評只背誦成法而不理解其因時制宜的宗旨。\\\\n【關鍵詞義】「寢說」指止息辯說；「麤」同「粗」，意謂文字可傳者只是較外在的層次；「體一」「摠要」分別指以一為根本、掌握統攝眾事的綱要。\\\\n【章法與思想】從救災立名、除害成功的條件性切入，轉論至人含德不言，再引《道德經》第一章說語言的限度，最後以三皇五帝三王「殊事同心」反駁照搬歷史痕跡。它並非否定文獻，而是要求由文獻追索原理。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-15\",\"chapterId\":\"wenzi_ch-2\",\"order\":15,\"canonicalText\":\"老子曰：心之精者，可以神化，而不可說道。聖人不降席而匡天下，情甚於號呼，故同言而信，信在言前也，同令而行，誠在令外也。聖人在上，民化如神，情以先之，動於上不應於下者，情令殊也。三月嬰兒未知利害，而慈母愛之愈篤者，情也。故言之用者變，變乎小哉，不言之用者變，變乎大哉。信，君子之言，忠，君子之意，忠信形於內，感動應乎外，賢聖之化也。\",\"sentenceIds\":[\"wenzi_ch-2_p-15_s-1\",\"wenzi_ch-2_p-15_s-2\",\"wenzi_ch-2_p-15_s-3\",\"wenzi_ch-2_p-15_s-4\",\"wenzi_ch-2_p-15_s-5\",\"wenzi_ch-2_p-15_s-6\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：心中精純的部分，可以產生神妙的感化，卻不能只靠言語說盡。聖人不必離開席位便能匡正天下，因為真情的力量勝過疾聲呼喊。說同樣的話而有人使人信服，是因可信早已存在於言語之前；頒布同樣的命令而有人使人遵行，是因真誠存在於命令之外。聖人在上，人民受到感化，迅速得如同神妙作用，因為真情先行。上位者有所行動而下民不響應，是因他的內情與命令彼此不同。三個月大的嬰兒還不知道利害，慈母卻更加深切地愛他，靠的就是真情。因此，運用言語造成的改變很小；不用言語而由真情造成的改變，才廣大深遠。信，是君子言語的準則；忠，是君子內心的真意。忠信形成於內，感動應驗於外，這就是賢聖的教化。\",\"analysis\":\"【主旨】本段說明命令有效的根據在發令者長期呈現的忠信與真情；言辭相同，內在是否真誠會造成不同的感化結果。\\\\n【版本提示】原文「情甚於●呼」含缺損字形，白話依全段「真情勝於言令」的對比處理，不擅自補定缺字。\\\\n【章法與思想】先提出精誠難以言盡，再比較「言前之信」「令外之誠」，以慈母愛嬰證明情感不待利害計算，最後界定信為言、忠為意。這段把不言之教落實為言行一致，而不是拒絕發佈政令。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-16\",\"chapterId\":\"wenzi_ch-2\",\"order\":16,\"canonicalText\":\"老子曰：子之死父，臣之死君，非出以求名也，恩心藏於中而不違其難也。君子之憯怛非正為也，自中出者也，亦察其所行，聖人不慚於影，君子慎其獨也，舍近期遠，塞矣。故聖人在上則民樂其治，在下則民慕其意，志不忘乎欲利人。\",\"sentenceIds\":[\"wenzi_ch-2_p-16_s-1\",\"wenzi_ch-2_p-16_s-2\",\"wenzi_ch-2_p-16_s-3\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：兒子為父親赴死，臣子為君主赴難，不是出於追求名聲，而是感恩之心藏在內部，使他不逃避對方的患難。君子的悲痛惻怛也不是刻意做給人看，而是發自內心；但仍須省察自己的行為。聖人面對影子也無愧，君子在獨處時仍謹慎。捨棄切近的內心根本，反去追求遙遠的名聲，便是閉塞不通。因此聖人在上位，人民喜愛他的治理；在下位，人民仰慕他的心意，因為他的志向始終不忘利益他人。\",\"analysis\":\"【題解與背景】\\\\n本段選自《文子》〈精誠〉第 25 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰子之死父臣之死君非出以求名也恩心藏於中……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「子」、「死」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-17\",\"chapterId\":\"wenzi_ch-2\",\"order\":17,\"canonicalText\":\"老子曰：勇士一呼，三軍皆闢，其出之誠，唱而不和，意而不載，中必有不合者也。不下席而匡天下者，求諸己也，故說之所不至者，容貌至焉，容貌所不至者，感忽至焉，感乎心發而成形，精之至者可形接，不可以照期。\",\"sentenceIds\":[\"wenzi_ch-2_p-17_s-1\",\"wenzi_ch-2_p-17_s-2\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：勇士一聲呼喊，三軍都退避，是因那聲音出於真誠勇氣。若有人領唱卻無人應和，心意發出卻不能承載於行動，內心必有不相契合之處。不離席位便能匡正天下的人，是向自己身上尋求根本。因此言語不能傳達的，容貌神色可以傳達；容貌神色仍不能到達的，心靈感應可以到達。感受由內心發動而形成外在表現；精誠到了極處，可以由形貌彼此感通，卻不能按預定時刻勉強求得。\",\"analysis\":\"【主旨】本段以勇士一呼使三軍退避，說明感召力來自內在誠意；若言語有人領唱卻無人應和，便顯示內心、表情和行動彼此不一致。\\\\n【章法與詞義】文章依「言說—容貌—感忽」逐層深入：言語不能到達的由神色傳達，神色不能到達的由內心感通。「求諸己」是先整頓自身，而非用命令強制外界；「不可以照期」意指精誠感通不能指定日期、按表強求。\\\\n【現代界限】此處的「形接」可理解為真誠透過聲氣、表情與行動被他人感受，不必推論成超自然心靈感應；政治感召也仍需制度責任配合。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-18\",\"chapterId\":\"wenzi_ch-2\",\"order\":18,\"canonicalText\":\"老子曰：言有宗，事有本，失其宗本，伎能雖多，不如寡言。害眾著倕而使斷其指，以期大巧之不可為也，故匠人智為，不以能以時，閉不知閉也，故必杜而後開。\",\"sentenceIds\":[\"wenzi_ch-2_p-18_s-1\",\"wenzi_ch-2_p-18_s-2\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：言論有宗旨，事情有根本；失去宗旨與根本，技巧才能即使很多，也不如少說。若為了使眾人厭棄技巧，便讓巧匠倕斷掉手指，以求天下不再從事機巧，這同樣不是合宜的方法。所以真正有智慧的工匠有所作為，並不只是炫耀能力，而是配合時機。只知封閉卻不明白封閉的道理，也不是真正的閉藏；因此必先確實杜塞，然後才可以開通。\",\"analysis\":\"【題解與背景】\\\\n本段選自《文子》〈精誠〉第 27 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰言有宗事有本失其宗本伎能雖多不如寡……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「老」、「子」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wenzi_ch-2_p-18）。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-19\",\"chapterId\":\"wenzi_ch-2\",\"order\":19,\"canonicalText\":\"老子曰：聖人之從事也，所由異路而同歸，存亡定傾若一，志不忘乎欲利人也。故秦楚燕魏之歌，異傳而皆樂，九夷八狄之哭，異聲而皆哀。夫歌者樂之微，哭者哀之效也，愔於中，發於外，故在所以感之矣。聖人之心，日夜不忘乎欲利人，其澤之所及亦遠矣。\",\"sentenceIds\":[\"wenzi_ch-2_p-19_s-1\",\"wenzi_ch-2_p-19_s-2\",\"wenzi_ch-2_p-19_s-3\",\"wenzi_ch-2_p-19_s-4\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：聖人辦事，所走的道路雖然不同，歸宿卻一致；無論救亡、安定危局，都用同一顆心對待，志向始終不忘利益人民。所以秦、楚、燕、魏的歌唱，傳唱方式不同，卻同樣表達歡樂；九夷八狄的哭泣，聲音不同，卻同樣表達悲哀。歌聲是歡樂的顯露，哭聲是悲哀的表現；感情蘊藏在內心，聲音發露於外，所以關鍵在於內心受到什麼感動。聖人的心日夜不忘利益人民，他的恩澤因此能達到很遠。\",\"analysis\":\"【題解與背景】\\\\n本段選自《文子》〈精誠〉第 28 節。屬於古代道家玄旨代表性經典，記述先賢關於主張順應自然、無為而治、清靜守柔與虛懷若谷之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「老子曰聖人之從事也所由異路而同歸存亡定傾若一……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「老」、「子」、「聖」、「人」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《文子》知行合一與經世致用之哲理觀念，展現老莊哲學對宇宙天道與人生通達境界之深刻體悟，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-20\",\"chapterId\":\"wenzi_ch-2\",\"order\":20,\"canonicalText\":\"老子曰：人無為而治，有為也即傷。無為而治者，為無為，為者不能無為也，不能無為者，不能有為也。人無言而神，有言即傷。無言乏神者，載無言，則傷有神之神者。\",\"sentenceIds\":[\"wenzi_ch-2_p-20_s-1\",\"wenzi_ch-2_p-20_s-2\",\"wenzi_ch-2_p-20_s-3\",\"wenzi_ch-2_p-20_s-4\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"老子說：人能不妄加作為，事情便得到治理；刻意強為，反會有所損傷。所謂以無為而治，是實踐不妄為；一味造作的人不能真正無為，而不能無為的人，也不能成就合宜的作為。人不靠多言而能呈現神妙作用；一旦執著言說，反會損傷它。傳本文句無言乏神者，載無言語義不穩，大意仍在說：若只把無言當成外在姿態，反而會損傷原本由內在精神產生的不言之化。\",\"analysis\":\"【主旨】本段辨析「無為」與「有為」、「無言」與「神化」：無為不是消極不做，無言也不是刻意閉口；一旦把它們模仿成外在姿態，就又落入造作。\\\\n【版本提示】末句「無言乏神者，載無言」在現有資料中句讀與字義不穩，白話只交代可由上下文確定的思想方向，保留後續版本校勘。\\\\n【章法與思想】前半以看似悖論的反覆語法釐清無為能成事，後半用同一結構談無言之教。核心在自然真實，不在機械遵守「什麼都不做、什麼都不說」。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"wenzi_ch-2_p-21\",\"chapterId\":\"wenzi_ch-2\",\"order\":21,\"canonicalText\":\"文子曰：名可強立，功可強成。昔南榮疇恥聖道而獨亡於己，南見老子，受教一言，精神曉靈，屯閔脩達，勤苦十日不食，如享太牢，是以明照海內，名立後世，智略天地，察分秋毫，稱譽華語，至今不休，此謂名可強立也。故田者不強，囷倉不滿，官御不勵，誠心不精，將相不強，功烈不成，王侯懈怠，汎世無名。至人潛行，譬猶雷霆之藏也，隨時而舉事，因資而立功，進退無難，無所不通。夫至人精誠內形，德流四方，見天下有利也，喜而不忘，天下有害也，憂若有喪。夫「憂民之憂者，民亦憂其憂，樂民之樂者，民亦樂其樂，故憂以天下，樂以天下，然而不王者，未之有也。」「聖人之法，始於不可見，終於不可及，處於不傾之地，積於不盡之倉，載於不竭之府。出令如流水之原，使民於不爭之官，開必得之門，不為不可成，不求不可得，不處不可久，不行不可復。」大人行可說之政，而人莫不順其命，命順則從，小而致大，命逆則以善為害，以成為敗。夫所謂大丈夫者，內強而外明，內強如天地，外明如日月，天地無不覆載，日月無不照明。大人以善示人，不變其故，不易其常，天下聽令，如草從風。政失於春，歲星盈縮，不居其常；政失於夏，熒惑逆行；政失於秋，太白不當，出入無常；政失於冬，辰星不效其鄉，四時失政，鎮星搖蕩，日月見謫，五星悖亂，彗星出。春政不失禾黍滋，夏政不失雨降時，秋政不失民殷昌，冬政不失國家寧康。\",\"sentenceIds\":[\"wenzi_ch-2_p-21_s-1\",\"wenzi_ch-2_p-21_s-2\",\"wenzi_ch-2_p-21_s-3\",\"wenzi_ch-2_p-21_s-4\",\"wenzi_ch-2_p-21_s-5\",\"wenzi_ch-2_p-21_s-6\",\"wenzi_ch-2_p-21_s-7\",\"wenzi_ch-2_p-21_s-8\",\"wenzi_ch-2_p-21_s-9\",\"wenzi_ch-2_p-21_s-10\",\"wenzi_ch-2_p-21_s-11\",\"wenzi_ch-2_p-21_s-12\",\"wenzi_ch-2_p-21_s-13\",\"wenzi_ch-2_p-21_s-14\",\"wenzi_ch-2_p-21_s-15\",\"wenzi_ch-2_p-21_s-16\"],\"sourceRefs\":[{\"label\":\"《文子》—中國哲學書電子化計劃\",\"edition\":\"李定生等《文子新書》本\",\"location\":\"https://ctext.org/wenzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《文子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/文子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"文子說：名聲可以靠努力建立，功業可以靠努力完成。從前南榮疇以不能通達聖道為恥，認為缺失只在自己，便南行拜見老子；受到一句教誨後，精神明悟，困頓阻滯都得到疏通。他勤苦修習，十天不吃飯，精神上卻像享用盛大的祭牲。因此明智能照察海內，名聲流傳後世；智慧包舉天地，辨察細如秋毫，讚譽美名至今不息。這就是名可以努力建立。所以耕田者不勤力，糧倉就不會充滿；官吏不勉力，誠意便不能精純；將相不奮發，功業便不能成就；王侯懈怠，也會終世無名。至人平時潛藏而行，好比雷霆隱伏；順應時機辦事，依靠已有條件立功，進退都不困難，處處通達。至人的精誠發自內心，德澤流佈四方；看見天下有利便欣喜而不忘，看見天下有害便憂傷如同遭逢喪事。所謂憂人民所憂，人民也會憂他所憂；樂人民所樂，人民也會樂他所樂。與天下同憂同樂而不能成王業的，從未有過。聖人的法則，開始時細微得看不見，最終成就高遠得難以企及；立於不會傾覆之地，積蓄於用之不盡的倉庫，收藏於取之不竭的府庫。發佈政令如流水有源，使人民處於無須爭奪的官制，開啟必能獲得的門路；不做不能成功的事，不求不能得到的物，不居不能長久的位置，不走不能返回的道路。大人施行可以使人悅服的政治，人民無不順從命令。命令順理，人民便服從，能由小成大；命令逆理，即使本意為善也會造成禍害，本來可成也會轉為失敗。所謂大丈夫，內在堅強而外在明察；內在堅強如天地，外在明察如日月。天地無不覆載，日月無不照耀。大人以善道昭示人民，不改變根本，不更易常則，天下聽命就像草隨風倒。古人認為春季政令失當，歲星便不循常度；夏令失當，熒惑便逆行；秋令失當，太白出入失常；冬令失當，辰星便不出現在應有方位。四時政令全失，鎮星搖蕩，日月顯出譴告，五星運行悖亂，彗星也會出現。春令不失，禾黍滋長；夏令不失，雨水按時；秋令不失，人民富盛；冬令不失，國家安寧。\",\"analysis\":\"【主旨】本段從南榮疇勤學說明功名須積累，再轉入至人與民同憂樂、政令須順理，末以傳統天人感應說四時政治的後果。\\\\n【關鍵詞義】「強」是勉力而非強迫；「太牢」是牛羊豕俱備的盛饌；「因資」指憑藉既有條件；歲星、熒惑、太白、辰星、鎮星分別是古代五星名稱。\\\\n【版本提示】「南榮疇恥聖道」「屯閔脩達」「官御不勵」等處傳本文句不穩；白話依勤學自勵的連續語意處理。末段星象屬古代政治宇宙觀，解析不把它當作現代自然科學因果。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"wenzi_ch-2_p-1_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-1\",\"order\":1,\"canonicalText\":\"老子曰：天致其高，地致其厚，日月照，列星朗，陰陽和，非有為焉，正其道而物自然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-1_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-1\",\"order\":2,\"canonicalText\":\"陰陽四時非生萬物也，雨露時降非養草木也，神明接，陰陽和，萬物生矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-1_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-1\",\"order\":3,\"canonicalText\":\"夫道者，藏精於內，棲神於心，靜漠恬惔，悅穆胸中，廓然無形，寂然無聲。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-1_s-4\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-1\",\"order\":4,\"canonicalText\":\"官府若無事，朝廷若無人，無隱士，無逸民，無勞役，無怨刑，天下莫不仰上之象，主之旨，絕國殊俗莫不重譯而至，非家至而人見之也，推其誠心，施之天下而已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-1_s-5\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-1\",\"order\":5,\"canonicalText\":\"故賞善罰暴者，正令也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-1_s-6\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-1\",\"order\":6,\"canonicalText\":\"其所以能行者，精誠也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-1_s-7\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-1\",\"order\":7,\"canonicalText\":\"令雖明不能獨行，必待精誠，故摠道以被民弗從者，精誠弗包也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-2_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-2\",\"order\":1,\"canonicalText\":\"老子曰：天設日月，列星辰，張四時，調陰陽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-2_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-2\",\"order\":2,\"canonicalText\":\"日以暴之，夜以息之，風以乾之，雨露以濡之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-2_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-2\",\"order\":3,\"canonicalText\":\"其生物也，莫見其所養而萬物長；\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-2_s-4\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-2\",\"order\":4,\"canonicalText\":\"其殺物也，莫見其所喪而萬物亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-2_s-5\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-2\",\"order\":5,\"canonicalText\":\"此謂神明。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-2_s-6\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-2\",\"order\":6,\"canonicalText\":\"是故聖人象之，其起福也，不見其所以而福起；\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-2_s-7\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-2\",\"order\":7,\"canonicalText\":\"其除禍也，不見其所由而禍除。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-2_s-8\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-2\",\"order\":8,\"canonicalText\":\"稽之不得，察之不虛，日計不足，歲計有餘，寂然無聲，一言而大動天下，是以天心動化者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-2_s-9\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-2\",\"order\":9,\"canonicalText\":\"故精誠內形，氣動於天，景星見，黃龍下，鳳皇至，醴泉出，嘉穀生，河不滿溢，海不波湧；\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-2_s-10\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-2\",\"order\":10,\"canonicalText\":\"逆天暴物，即日月薄蝕，五星失行，四時相乘，晝明宵光，山崩川涸，冬雷夏霜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-2_s-11\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-2\",\"order\":11,\"canonicalText\":\"天之與人，有以相通，故國之沮亡也，天文變，世或亂，虹蜺見，萬物有以相連，精氣有以相薄，故神明之事，不可以智巧為也，不可以強力致也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-2_s-12\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-2\",\"order\":12,\"canonicalText\":\"故大人與天地合德，與日月合明，與鬼神合靈，與四時合信，懷天心，抱地氣，執沖含和，不下堂而行四海，變易習俗，民化遷善，若生諸己，能以神化者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-3_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-3\",\"order\":1,\"canonicalText\":\"老子曰：夫人道者，全性保真，不虧其身，遭急迫難，精通乎天，若乃未始出其宗者，何為而不成，死生同域，不可脅凌，又況官天地，懷萬物，返造化，含至和，而已未嘗死者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-3_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-3\",\"order\":2,\"canonicalText\":\"精誠形乎內，而外喻於人心，此不傳之道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-3_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-3\",\"order\":3,\"canonicalText\":\"聖人在上，懷道而不言，澤及萬民，故不言之教，芒乎大哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-3_s-4\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-3\",\"order\":4,\"canonicalText\":\"君臣乖心，倍譎見於天，神氣相應，微矣，此謂不言之辯，不道之道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-3_s-5\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-3\",\"order\":5,\"canonicalText\":\"夫召遠者使無為焉，親近者言無事焉，唯夜行者能有之，卻走馬以糞，車軌不接於遠方之外，是謂坐馳陸沉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-3_s-6\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-3\",\"order\":6,\"canonicalText\":\"天道無私就也，無私去也，能者有餘，詘者不足，順之者利，逆之者兇。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-3_s-7\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-3\",\"order\":7,\"canonicalText\":\"是故以智為治者難以持國，唯同乎大和而持自然應者，為能有之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-4_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-4\",\"order\":1,\"canonicalText\":\"老子曰：夫道之與德，若圍之與革，遠之即近，近之即鉕，稽之不得，察之不虛。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-4_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-4\",\"order\":2,\"canonicalText\":\"是故聖人若鏡，不將不迎，應而不藏，不物而不傷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-4_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-4\",\"order\":3,\"canonicalText\":\"其得之也，乃失之也，其失之也，乃得之也，故通於大和者，闇若醇醉而甘臥以遊其中，若未始出其宗，是謂大通，此假不用能成其用也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-5_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-5\",\"order\":1,\"canonicalText\":\"老子曰：昔黃帝之治天下，理日月之行，治陰陽之氣，節四時之度，正律曆之數，別男女，明上下，使強不掩弱，眾不暴寡，民保命而不夭，歲時熟而不兇，百官正而無私，上下調而無尤，法令明而不闇，輔佐公而不阿，田者讓畔，道不拾遺，市不預賈，故於此時，日月星辰不失其行，風雨時節，五穀豐昌，鳳皇翔於庭，麒麟遊於郊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-5_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-5\",\"order\":2,\"canonicalText\":\"虙犧氏之王天下，枕方寢繩，殺秋約冬，負方州，抱員天，陰陽所擁沈不通者竅理之，逆氣戾物傷民厚積者絕止之，其民童蒙不知西東，視瞑瞑，行蹎蹎，侗然自得，莫知其所由，浮游汎然，不知所本，罔養不知所如往，當此之時，禽獸蟲蛇無不懷其爪牙，藏其螫毒，功揆天地。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-5_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-5\",\"order\":3,\"canonicalText\":\"至黃帝要繆乎太祖之下，然而不章其功，不揚其名，隱真人之道，以從天地之固然，何即道德上通，而智故消滅也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-6_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-6\",\"order\":1,\"canonicalText\":\"老子曰：天不定，日月無所載，地不定，草木無所立，身不寧，是非無所形，是故有真人而後有真智，其所持者不明，何知吾所謂知之非不知與？\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-6_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-6\",\"order\":2,\"canonicalText\":\"積惠重貨，使萬民欣欣，人樂其生者，仁也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-6_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-6\",\"order\":3,\"canonicalText\":\"舉大功，顯令名，體君臣，正上下，明親疏，存危國，繼絕世，立無後者，義也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-6_s-4\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-6\",\"order\":4,\"canonicalText\":\"閉九竅，藏志意，棄聰明，反無識，芒然仿佯乎塵垢之外，逍遙乎無事之業，含陰吐陽而與萬物同和者，德也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-6_s-5\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-6\",\"order\":5,\"canonicalText\":\"是故道散而為德，德溢而為仁義，仁義立而道德廢矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-7_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-7\",\"order\":1,\"canonicalText\":\"老子曰：神越者言華，德蕩者行偽，至精芒乎中，而言行觀乎外，此不免以身役物也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-7_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-7\",\"order\":2,\"canonicalText\":\"精有愁盡而行無窮極，所守不定而外淫於世俗之風，是故聖人內脩道術而不外飾仁義，知九竅四支之宜，而遊乎精神之和，此聖人之遊也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-8_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-8\",\"order\":1,\"canonicalText\":\"老子曰：若夫聖人之遊也，即動乎至虛，遊心乎太無，馳於方外，行於無門，聽於無聲，視於無形，不拘於世，不繫於俗。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-8_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-8\",\"order\":2,\"canonicalText\":\"故聖人所以動天下者，真人不過，賢人所以矯世者，聖人不觀。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-8_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-8\",\"order\":3,\"canonicalText\":\"夫人拘於世俗，必形繫而神泄，故不免於別，使我可拘係者，必其命有在外者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-9_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-9\",\"order\":1,\"canonicalText\":\"老子曰：人主之思，神不馳於胸中，智不出於四域，懷其仁誠之心，甘雨以時，五穀蕃殖，春生夏長，秋收冬藏，月省時考，終歲獻貢，養民以公，威厲以誠，法省不煩，教化如神，法寬刑緩，囹圄空虛，天下一俗，莫懷姦心，此聖人之思也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-9_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-9\",\"order\":2,\"canonicalText\":\"夫上好取而無量，即下貪功而無讓，民貧苦而分爭生，事力勞而無功，智詐萌生，盜賊滋彰，上下相怨，號令不行，夫水濁者魚噞，政苛者民亂，上多欲即下多詐，上煩擾即下不定，上多求即下交爭，不治其本而救之於末，無以異於鑿渠而止水，抱薪而救火。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-9_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-9\",\"order\":3,\"canonicalText\":\"聖人事省而治求，寡而贍，不施而仁，不言而信，不求而得，不為而成，懷自然，保至真，抱道推誠，天下從之如響之應聲，影之像形，所脩者本也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-10_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-10\",\"order\":1,\"canonicalText\":\"老子曰：精神越於外，智慮蕩於內者，不能治形，神之所用者遠，則所遺者近。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-10_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-10\",\"order\":2,\"canonicalText\":\"故「不出於戶以知天下，不窺於牖以知天道，其出彌遠，其知彌少。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-10_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-10\",\"order\":3,\"canonicalText\":\"」此言精誠發於內，神氣動於天也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-11_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-11\",\"order\":1,\"canonicalText\":\"老子曰：冬日之陽，夏日之陰，萬物歸之而莫之使，極自然至精之感，弗召自來，不去而往，窈窈冥冥，不知所為者而功自成，待目而照見，待言而使命，其於治難矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-11_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-11\",\"order\":2,\"canonicalText\":\"皋陶喑而為大理，天下無虐刑，有貴乎言者也，師曠瞽而為太宰，晉國無亂政，有貴乎見者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-11_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-11\",\"order\":3,\"canonicalText\":\"不言之令，不視之見，聖人所以為師也，民之化上，不從其言從其所行，故人君好勇，弗使鬥爭而國家多難，其漸必有劫殺之亂矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-11_s-4\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-11\",\"order\":4,\"canonicalText\":\"人君好色，弗使風議而國家昏亂，其積至於淫泆之難，故聖人精誠別於內，好憎明於外，出言以副情，發號以明指。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-11_s-5\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-11\",\"order\":5,\"canonicalText\":\"是故刑罰不足以移風，殺戮不足以禁姦，唯神化為貴，精至為神，精之所動，若春氣之生，秋氣之殺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-11_s-6\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-11\",\"order\":6,\"canonicalText\":\"故君子者，其猶射者也，於此毫末，於彼尋丈矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-11_s-7\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-11\",\"order\":7,\"canonicalText\":\"故理人者，慎所以感之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-12_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-12\",\"order\":1,\"canonicalText\":\"老子曰：懸法設賞而不能移風易俗者，誠心不抱，故聽其音則知其風，觀其樂即知其俗，見其俗即知其化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-12_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-12\",\"order\":2,\"canonicalText\":\"夫抱真效誠者，感動天地，神踰方外，令行禁止，誠通其道而達其意，雖無一言，天下萬民、禽獸、鬼神與之變化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-12_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-12\",\"order\":3,\"canonicalText\":\"故太上神化，其次使不得為非，其下賞賢而罰暴。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-13_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-13\",\"order\":1,\"canonicalText\":\"老子曰：大道無為，無為即無有，無有者不居也，不居者即處無形，無形者不動，不動者無言也，無言者即靜而無聲無形，無聲無形者，視之不見，聽之不聞，是謂微妙，是謂至神，「綿綿若存」，「是謂天地根。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-13_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-13\",\"order\":2,\"canonicalText\":\"」道無聲，故聖人強為之形，以一句為名天地之道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-13_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-13\",\"order\":3,\"canonicalText\":\"大以小為本，多以少為始，天子以天地為品，以萬物為資，功德至大，勢名至貴，二德之美與天地配，故不可不軌大道以為天下母。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-14_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-14\",\"order\":1,\"canonicalText\":\"老子曰：振窮補急則名生利起，除害即功成，世無災害，雖聖無所施其德，上下和睦，雖賢無所立其功。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-14_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-14\",\"order\":2,\"canonicalText\":\"故至人之治，含德抱道，推誠施無窮之智，寢說而不言天下莫知貴其不言者，故「道可道，非常道也，名可名，非常名也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-14_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-14\",\"order\":3,\"canonicalText\":\"」著於竹帛，鏤於金石，可傳於人者，皆其麤也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-14_s-4\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-14\",\"order\":4,\"canonicalText\":\"三皇五帝三王，殊事而同心，異路而同歸，末世之學者，不知道之所體一德之所摠要取成事之跡跪坐而言之，雖博學多聞，不免於亂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-15_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-15\",\"order\":1,\"canonicalText\":\"老子曰：心之精者，可以神化，而不可說道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-15_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-15\",\"order\":2,\"canonicalText\":\"聖人不降席而匡天下，情甚於號呼，故同言而信，信在言前也，同令而行，誠在令外也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-15_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-15\",\"order\":3,\"canonicalText\":\"聖人在上，民化如神，情以先之，動於上不應於下者，情令殊也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-15_s-4\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-15\",\"order\":4,\"canonicalText\":\"三月嬰兒未知利害，而慈母愛之愈篤者，情也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-15_s-5\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-15\",\"order\":5,\"canonicalText\":\"故言之用者變，變乎小哉，不言之用者變，變乎大哉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-15_s-6\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-15\",\"order\":6,\"canonicalText\":\"信，君子之言，忠，君子之意，忠信形於內，感動應乎外，賢聖之化也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-16_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-16\",\"order\":1,\"canonicalText\":\"老子曰：子之死父，臣之死君，非出以求名也，恩心藏於中而不違其難也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-16_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-16\",\"order\":2,\"canonicalText\":\"君子之憯怛非正為也，自中出者也，亦察其所行，聖人不慚於影，君子慎其獨也，舍近期遠，塞矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-16_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-16\",\"order\":3,\"canonicalText\":\"故聖人在上則民樂其治，在下則民慕其意，志不忘乎欲利人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-17_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-17\",\"order\":1,\"canonicalText\":\"老子曰：勇士一呼，三軍皆闢，其出之誠，唱而不和，意而不載，中必有不合者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-17_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-17\",\"order\":2,\"canonicalText\":\"不下席而匡天下者，求諸己也，故說之所不至者，容貌至焉，容貌所不至者，感忽至焉，感乎心發而成形，精之至者可形接，不可以照期。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-18_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-18\",\"order\":1,\"canonicalText\":\"老子曰：言有宗，事有本，失其宗本，伎能雖多，不如寡言。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-18_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-18\",\"order\":2,\"canonicalText\":\"害眾著倕而使斷其指，以期大巧之不可為也，故匠人智為，不以能以時，閉不知閉也，故必杜而後開。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-19_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-19\",\"order\":1,\"canonicalText\":\"老子曰：聖人之從事也，所由異路而同歸，存亡定傾若一，志不忘乎欲利人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-19_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-19\",\"order\":2,\"canonicalText\":\"故秦楚燕魏之歌，異傳而皆樂，九夷八狄之哭，異聲而皆哀。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-19_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-19\",\"order\":3,\"canonicalText\":\"夫歌者樂之微，哭者哀之效也，愔於中，發於外，故在所以感之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-19_s-4\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-19\",\"order\":4,\"canonicalText\":\"聖人之心，日夜不忘乎欲利人，其澤之所及亦遠矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-20_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-20\",\"order\":1,\"canonicalText\":\"老子曰：人無為而治，有為也即傷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-20_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-20\",\"order\":2,\"canonicalText\":\"無為而治者，為無為，為者不能無為也，不能無為者，不能有為也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-20_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-20\",\"order\":3,\"canonicalText\":\"人無言而神，有言即傷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-20_s-4\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-20\",\"order\":4,\"canonicalText\":\"無言乏神者，載無言，則傷有神之神者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-1\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":1,\"canonicalText\":\"文子曰：名可強立，功可強成。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-2\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":2,\"canonicalText\":\"昔南榮疇恥聖道而獨亡於己，南見老子，受教一言，精神曉靈，屯閔脩達，勤苦十日不食，如享太牢，是以明照海內，名立後世，智略天地，察分秋毫，稱譽華語，至今不休，此謂名可強立也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-3\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":3,\"canonicalText\":\"故田者不強，囷倉不滿，官御不勵，誠心不精，將相不強，功烈不成，王侯懈怠，汎世無名。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-4\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":4,\"canonicalText\":\"至人潛行，譬猶雷霆之藏也，隨時而舉事，因資而立功，進退無難，無所不通。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-5\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":5,\"canonicalText\":\"夫至人精誠內形，德流四方，見天下有利也，喜而不忘，天下有害也，憂若有喪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-6\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":6,\"canonicalText\":\"夫「憂民之憂者，民亦憂其憂，樂民之樂者，民亦樂其樂，故憂以天下，樂以天下，然而不王者，未之有也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-7\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":7,\"canonicalText\":\"」「聖人之法，始於不可見，終於不可及，處於不傾之地，積於不盡之倉，載於不竭之府。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-8\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":8,\"canonicalText\":\"出令如流水之原，使民於不爭之官，開必得之門，不為不可成，不求不可得，不處不可久，不行不可復。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-9\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":9,\"canonicalText\":\"」大人行可說之政，而人莫不順其命，命順則從，小而致大，命逆則以善為害，以成為敗。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-10\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":10,\"canonicalText\":\"夫所謂大丈夫者，內強而外明，內強如天地，外明如日月，天地無不覆載，日月無不照明。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-11\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":11,\"canonicalText\":\"大人以善示人，不變其故，不易其常，天下聽令，如草從風。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-12\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":12,\"canonicalText\":\"政失於春，歲星盈縮，不居其常；\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-13\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":13,\"canonicalText\":\"政失於夏，熒惑逆行；\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-14\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":14,\"canonicalText\":\"政失於秋，太白不當，出入無常；\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-15\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":15,\"canonicalText\":\"政失於冬，辰星不效其鄉，四時失政，鎮星搖蕩，日月見謫，五星悖亂，彗星出。\",\"chunks\":[],\"tags\":[]},{\"id\":\"wenzi_ch-2_p-21_s-16\",\"workId\":\"wenzi\",\"chapterId\":\"wenzi_ch-2\",\"passageId\":\"wenzi_ch-2_p-21\",\"order\":16,\"canonicalText\":\"春政不失禾黍滋，夏政不失雨降時，秋政不失民殷昌，冬政不失國家寧康。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
